#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000078.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'498683': 'Complete recessed wooden icon with three haloed angels at left and kneeling Alexander of Svir at right before a wooden building and trees. All irregular board edges and the inscription field visible. Source native IK 65 composition matches; no crop or placeholder.', '498408': 'Full Kazan Mother-and-Child icon within its rectangular red edge, with sculpted gilded halos and collar. Museum-supplied gray surround retained on all sides. Full physical composition visible; background explains photographic proportions. Native IK 184 identity matches; not a similar Kazan version.', '498698': 'Full horizontal icon showing Christ twice distributing communion to apostles on either side of central altar. Broad ochre border and worn lower surface retained. Exact IK 79 composition, no cropped scene or substitute. Minute inscriptions not independently read.', '498556': 'Complete single painted board with central Crucifixion and four surrounding narrative/saint fields, including large Mother-and-Child upper right and long-bearded Haralampius lower right. Side saints, inscriptions, worn top center and full outer edge retained. One IK 319 object, not separate artworks per scene.', '498714': 'Complete Znameniye panel with raised hands, Christ medallion on the Mother’s chest, red and blue winged angelic figures, and two side saints. Full board and dark-red outer edges retained. Fine cracking belongs to source condition. Exact native IK 91 composition matches.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Individual actual derivative viewed. The source_display_placeholder size heuristic flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==5
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. Originals decoded and hashed; derivatives individually visually viewed.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('5 actual per-image visual decisions and complete file checks saved')
